package application.domain.services.fulfillment;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class RequestReturnService implements RequestReturnUseCase { private final OrderRepositoryPort orders; private final ReturnRequestRepositoryPort returns; private final OperationAuditPort audit; public RequestReturnService(OrderRepositoryPort o,ReturnRequestRepositoryPort r,OperationAuditPort a){orders=o;returns=r;audit=a;}
 public ReturnRequest requestReturn(User actor,String oid,String rid,Product product,int quantity,String reason){Order o=ServiceSupport.required(orders.findById(oid),"Order",oid);ServiceSupport.sameCustomer(actor,o.getCustomer());if(o.getStatus()!=DomainTypes.OrderStatus.DELIVERED)throw new DomainRuleException("Only delivered orders can be returned");if(product!=null&&!o.getItems().stream().anyMatch(i->i.product().getId().equals(product.getId())&&i.quantity()>=quantity))throw new DomainRuleException("Product or quantity is not part of order");ReturnRequest r=returns.save(new ReturnRequest(rid,o,product,quantity,reason));o.changeStatus(DomainTypes.OrderStatus.RETURN_REQUESTED);orders.update(o);audit.record(actor,"REQUEST_RETURN",rid,Map.of("orderId",oid));return r;}
}
